def setup_music():
    upyxel.sounds(0).mml(a1 + a2 + a3 + a4 + a5 + a6)
    upyxel.sounds(1).mml(b1 + b2 + b3 + b4 + b5 + b6)
    upyxel.sounds(2).mml(c1 + c2 + c3 + c4 + c5 + c6 + c7 + c8 + c9 + c10)
    upyxel.sounds(3).mml(d1 + d2 + d3 + d4 + d5 + d6 + d7 + d8 + d9 + d10)

    # Music 的第 1～4 个序列依次映射到通道 0～3。
    upyxel.musics(0).set([0], [1], [2], [3])


def main():
    audio = audio_service.audio
    audio_inited = False
    upyxel_inited = False

    try:
        audio.init(
            enable_input=False,
            enable_output=True,
            with_opus_encoder=False,
            with_opus_decoder=False,
        )
        audio_inited = True
        audio.configure(output_volume=100)

        upyxel.init(start_audio=True)
        upyxel_inited = True
        setup_music()

        started = time.ticks_ms()
        upyxel.playm(0, should_loop=True)
        print("四声部 MML Music 开始播放，持续 60 秒")

        def update(rt):
            if time.ticks_diff(time.ticks_ms(), started) >= DEMO_DURATION_MS:
                rt.quit()

        def draw(rt):
            rt.cls(1)
            rt.text(0, 0, "MMLmusic", 7)
            for channel in range(4):
                color = 10 if rt.play_pos(channel) is not None else 13
                rt.text(2 + channel * 8, 8, str(channel), color)

        upyxel.run(update, draw, fps=FPS)
        print("四声部 MML Music 演示结束")
    finally:
        if upyxel_inited:
            try:
                upyxel.stop()
            except Exception:
                pass
            try:
                upyxel.destroy()
            except Exception:
                pass
        if audio_inited:
            try:
                audio.deinit()
            except Exception:
                pass


main()
